@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Space+Grotesk:wght@500;600;700&display=swap');
:root{--ink:#28233a;--muted:#8c879c;--purple:#7655d9;--lav:#eee8ff;--pink:#ff7f9f;--cream:#fffdf9;--line:#eeeaf3;--green:#57bd9d}*{box-sizing:border-box}body{margin:0;background:#f6f3fb;color:var(--ink);font-family:'DM Sans',sans-serif;min-height:100vh;background-image:radial-gradient(#e9e2f4 1px,transparent 1px);background-size:22px 22px}.app-shell{max-width:1180px;margin:0 auto;padding:18px 26px 12px}.topbar{height:48px;display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}.brand{display:flex;gap:8px;align-items:center;text-decoration:none;color:var(--ink);font:700 19px 'Space Grotesk',sans-serif;letter-spacing:-.7px}.brand-icon{display:grid;place-items:center;background:var(--purple);color:white;width:30px;height:30px;border-radius:10px;font-size:18px}.brand-pop{color:var(--purple)}.top-note{font-size:10px;letter-spacing:1.55px;font-weight:800;color:#8e879e;display:flex;align-items:center;gap:8px}.live-dot,.caption-dot{width:7px;height:7px;border-radius:50%;background:#5fc6a2;display:inline-block}.icon-button,.round-button{border:0;cursor:pointer;background:white;color:#6b5c82;box-shadow:0 3px 12px #50436612}.icon-button{width:36px;height:36px;border-radius:12px;font-size:18px}.game-layout{display:grid;grid-template-columns:minmax(0,1.58fr) minmax(310px,.88fr);gap:18px;align-items:stretch}.stage-card,.wardrobe-card{background:var(--cream);border:1px solid #fff;border-radius:22px;box-shadow:0 12px 35px #44335f0c}.stage-card{padding:18px 20px 14px;min-width:0}.stage-topline{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}.eyebrow{font-size:9px;font-weight:800;letter-spacing:1.5px;color:#a49bb4}.stage-topline h1,.wardrobe-heading h2{font:700 23px 'Space Grotesk',sans-serif;letter-spacing:-.8px;margin:3px 0 0}.sparkle{font-size:15px;color:#ffbe47;vertical-align:3px}.round-button{width:36px;height:36px;border-radius:12px;font-size:22px}.stage{height:392px;position:relative;overflow:hidden;border-radius:18px;background:linear-gradient(150deg,#ede7ff 0%,#fce9f0 100%);display:flex;justify-content:center;align-items:flex-end}.stage-rays{position:absolute;width:380px;height:380px;top:-115px;left:50%;transform:translateX(-50%);background:repeating-conic-gradient(from 6deg at 50% 50%,#fff7 0deg 7deg,transparent 7deg 17deg);border-radius:50%;opacity:.8}.stage-floor{position:absolute;bottom:30px;width:62%;height:34px;background:#d9c8eb;border-radius:50%;filter:blur(1px);opacity:.58}.character-wrap{position:relative;z-index:2;height:365px;width:260px;transform-origin:50% 100%;transition:transform .18s ease;filter:drop-shadow(0 3px 3px #59427312)}#avatar{height:100%;width:100%;overflow:visible}.speech-bubble{position:absolute;z-index:3;top:24px;left:26px;max-width:190px;background:white;padding:11px 15px;border-radius:14px 14px 14px 3px;font-size:12px;font-weight:700;color:#64577c;box-shadow:0 5px 16px #47365411;transform:rotate(-2deg)}.speech-bubble:after{content:'';position:absolute;bottom:-6px;left:14px;width:13px;height:13px;background:white;transform:rotate(45deg)}.style-stamp{position:absolute;right:24px;top:28px;display:flex;flex-direction:column;align-items:center;gap:3px;color:#8e789a;font-size:9px;font-weight:800;letter-spacing:1px;transform:rotate(7deg)}.style-stamp span:first-child{font-size:31px}.stage-caption{position:absolute;right:14px;bottom:9px;z-index:3;color:#857f93;font-size:9px;font-weight:600;display:flex;align-items:center;gap:6px}.caption-dot{width:6px;height:6px}.action-area{display:grid;grid-template-columns:1fr auto;column-gap:12px;row-gap:12px;align-items:center;padding:15px 3px 11px}.action-copy{display:flex;flex-direction:column;gap:3px}.action-copy strong{font:700 13px 'Space Grotesk',sans-serif}.action-copy span{font-size:10px;color:var(--muted)}.pull-control{display:flex;align-items:center;gap:8px}.pull-control label{font-size:9px;letter-spacing:1px;font-weight:800;color:#a39bae}.pull-control input{width:76px;accent-color:var(--pink)}.pull-control span{display:grid;place-items:center;background:#ffedf1;border-radius:8px;width:24px;height:24px;color:#e25d81;font-size:12px;font-weight:800}.wedgie-button{grid-column:1/-1;width:100%;height:45px;border:0;border-radius:13px;background:linear-gradient(100deg,#7655d9,#9470e8);color:white;font:800 11px 'DM Sans',sans-serif;letter-spacing:1.1px;display:flex;align-items:center;justify-content:center;gap:11px;cursor:pointer;box-shadow:0 5px 0 #5940b2;transition:transform .12s,box-shadow .12s}.wedgie-button:active{transform:translateY(4px);box-shadow:0 1px 0 #5940b2}.button-icon{font-size:19px}.button-arrow{margin-left:auto;margin-right:15px;font-size:18px}.score-row{height:38px;display:flex;align-items:center;gap:10px;border-top:1px solid #f1edf5;padding:10px 1px 0}.score-label{display:flex;align-items:center;gap:5px;font-size:8px;letter-spacing:.8px;font-weight:800;color:#9e96aa;white-space:nowrap}.score-star{font-size:15px;color:#ffbc46}.score-track{flex:1;background:#f1eef5;border-radius:10px;height:7px;overflow:hidden}.score-fill{height:100%;width:0;background:linear-gradient(90deg,#ff9aae,#ffcb67);border-radius:10px;transition:width .5s}.score-row>strong{font:700 13px 'Space Grotesk',sans-serif;min-width:26px}.combo{font-size:8px;font-weight:800;color:#aa9eb9;letter-spacing:.8px;min-width:44px;text-align:right}.wardrobe-card{padding:20px 20px 14px;display:flex;flex-direction:column;min-width:0}.wardrobe-heading{display:flex;align-items:center;justify-content:space-between}.wardrobe-heading h2{font-size:21px}.hanger{color:#d7c8f3;font-size:29px;transform:rotate(-22deg)}.tabs{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;margin:17px 0 12px;padding:4px;background:#f5f2f8;border-radius:11px}.tab{height:33px;border:0;background:transparent;border-radius:8px;color:#958ca3;font:700 11px 'DM Sans',sans-serif;cursor:pointer}.tab.active{background:white;color:var(--purple);box-shadow:0 2px 6px #38244f12}.options-panel{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;min-height:208px;align-content:start}.option{border:1px solid #eeeaf2;background:#fff;border-radius:12px;padding:8px 5px 7px;min-height:91px;cursor:pointer;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;color:#716b7d;transition:.15s;position:relative}.option:hover{border-color:#d6c6fb;transform:translateY(-2px)}.option.selected{border:1.5px solid var(--purple);background:#faf8ff;box-shadow:0 3px 9px #6545c914;color:#5d43b1}.option-icon{height:39px;min-width:42px;border-radius:10px;display:grid;place-items:center;background:#f8f5fb;font-size:24px}.option-name{font-size:9px;font-weight:700;white-space:nowrap}.option.selected:after{content:'✓';position:absolute;right:6px;top:5px;width:15px;height:15px;border-radius:50%;background:var(--purple);color:white;font-size:9px;display:grid;place-items:center}.color-section{border-top:1px solid var(--line);padding-top:12px;margin-top:8px}.section-title{display:flex;justify-content:space-between;font-size:9px;font-weight:800;letter-spacing:1px;color:#a39bac}.selected-color{letter-spacing:0;font-size:10px;font-weight:600;color:#81788d}.swatches{display:flex;gap:9px;margin:10px 0 0}.swatch{width:23px;height:23px;border:2px solid white;box-shadow:0 0 0 1px #e8e3ed;border-radius:50%;cursor:pointer;padding:0;transition:.15s}.swatch.active{box-shadow:0 0 0 2px var(--purple);transform:scale(1.09)}.name-row{border-top:1px solid var(--line);margin-top:13px;padding-top:12px;display:flex;flex-direction:column;gap:7px}.name-row label{font-size:8px;font-weight:800;letter-spacing:1px;color:#a39bac}.name-row input{width:100%;border:1px solid #eeeaf2;border-radius:9px;background:#fff;padding:9px 11px;color:var(--ink);font:600 12px 'DM Sans',sans-serif;outline:none}.name-row input:focus{border-color:#ae98e9}.reset-button{background:transparent;border:0;color:#9d91af;margin:10px auto 0;padding:5px;font:700 10px 'DM Sans',sans-serif;cursor:pointer}.footer-note{margin-top:auto;border-radius:10px;background:#f5f1fb;padding:9px 10px;color:#8c819d;font-size:9px;text-align:center}.footer-note span{color:#f18aab}.page-footer{text-align:center;padding:13px 0 0;color:#aea6ba;font-size:8px;letter-spacing:1.3px;font-weight:800}.page-footer span{padding:0 6px;color:#ef9cba}.toast{position:fixed;left:50%;bottom:22px;transform:translate(-50%,20px);background:#332b45;color:white;padding:10px 16px;border-radius:11px;font-size:12px;font-weight:700;opacity:0;pointer-events:none;transition:.25s;z-index:10;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.bounce{animation:bounce .85s cubic-bezier(.25,.7,.25,1)}@keyframes bounce{0%{transform:translateY(0) rotate(0)}12%{transform:translateY(3px) rotate(-5deg) scaleX(.98)}32%{transform:translateY(-32px) rotate(4deg)}50%{transform:translateY(-8px) rotate(-3deg)}67%{transform:translateY(-22px) rotate(2deg)}82%{transform:translateY(0) rotate(0)}90%{transform:translateY(-7px)}100%{transform:translateY(0)}}.sparkle-on{animation:twinkle .75s ease-out}@keyframes twinkle{0%{opacity:0;transform:scale(.3)}35%{opacity:1;transform:scale(1.1)}100%{opacity:0;transform:scale(.7)}}
@media(min-height:850px){.app-shell{padding-top:28px}.stage{height:min(45vh,440px)}.character-wrap{height:min(41vh,410px)}}
@media(max-width:780px){.app-shell{padding:12px 14px 9px}.topbar{margin-bottom:10px}.game-layout{grid-template-columns:1fr;gap:12px}.stage-card{padding:14px 14px 12px}.stage{height:min(49vh,390px);min-height:280px}.character-wrap{height:min(45vh,365px)}.wardrobe-card{padding:16px 15px 12px}.options-panel{min-height:0;grid-template-columns:repeat(3,1fr)}.option{min-height:83px}.wardrobe-heading h2{font-size:20px}.footer-note{margin-top:10px}.page-footer{padding:10px 0 2px}.action-area{padding:12px 2px 10px}.speech-bubble{top:17px;left:14px}.style-stamp{right:12px;top:20px}.stage-caption{right:8px;font-size:8px}}
@media(max-width:380px){.app-shell{padding-left:9px;padding-right:9px}.stage{min-height:260px}.action-copy span{font-size:9px}.pull-control{gap:4px}.pull-control input{width:58px}.option{min-height:76px}.option-icon{height:34px}.stage-caption{font-size:7px}.top-note{font-size:8px}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}

const palette=[{name:'Berry',hex:'#d85e83'},{name:'Sky',hex:'#5a9ed6'},{name:'Lemon',hex:'#f2bd4b'},{name:'Mint',hex:'#56b99c'},{name:'Lavender',hex:'#9871d5'},{name:'Coral',hex:'#f17d61'},{name:'Ink',hex:'#484257'}];
const catalog={
 tops:[{id:'tee',name:'Graphic tee',icon:'👕'},{id:'hoodie',name:'Cozy hoodie',icon:'🧥'},{id:'tank',name:'Sporty tank',icon:'🎽'},{id:'underwear',name:'Comfy undies',icon:'🩱'}],
 bottoms:[{id:'jeans',name:'Cool jeans',icon:'👖'},{id:'shorts',name:'Bouncy shorts',icon:'🩳'},{id:'skirt',name:'Swishy skirt',icon:'👗'},{id:'briefs',name:'Comfy briefs',icon:'🩲'},{id:'joggers',name:'Joggers',icon:'🧶'}],
 extras:[{id:'glasses',name:'Star shades',icon:'🕶️'},{id:'cap',name:'Cool cap',icon:'🧢'},{id:'bow',name:'Hair bow',icon:'🎀'},{id:'scarf',name:'Party scarf',icon:'🧣'},{id:'sneakers',name:'Fresh kicks',icon:'👟'},{id:'none',name:'No extra',icon:'✦'}]
};
const state={tab:'tops',top:'tee',bottom:'jeans',extra:'glasses',colors:{tops:'#5a9ed6',bottoms:'#9871d5',extras:'#ff7f9f'},score:0,combo:0,lastTug:0,busy:false,sound:false};
const $=s=>document.querySelector(s), panel=$('#optionsPanel'), avatar=$('#avatar');
function drawTop(){const c=state.colors.tops;let shape='';if(state.top==='tee')shape=`<path d="M138 157 L121 165 L104 202 L127 216 L139 197 L136 248 Q180 260 224 248 L221 197 L234 216 L257 202 L239 164 L222 157 L208 172 Q180 187 152 172Z" fill="${c}" stroke="#fff" stroke-width="3" stroke-linejoin="round"/><path d="M161 175 Q180 183 199 175" fill="none" stroke="#ffffff88" stroke-width="3"/>`;
if(state.top==='hoodie')shape=`<path d="M137 157 L120 166 L101 205 L126 221 L139 201 L135 252 Q180 263 225 252 L221 201 L235 221 L260 205 L239 166 L222 157 L207 173 Q180 190 153 173Z" fill="${c}" stroke="#fff" stroke-width="3" stroke-linejoin="round"/><path d="M161 164 Q180 143 199 164 L194 177 Q180 185 166 177Z" fill="${c}" stroke="#fff" stroke-width="3"/><path d="M160 235 Q180 227 200 235 L197 246 Q180 251 163 246Z" fill="#ffffff44"/><path d="M176 187v36m9-36v36" stroke="#fff" stroke-width="2"/>`;
if(state.top==='tank')shape=`<path d="M142 158 Q152 148 163 151 L168 173 Q180 180 192 173 L197 151 Q211 148 220 158 L230 211 Q207 225 180 210 Q153 225 130 211Z" fill="${c}" stroke="#fff" stroke-width="3" stroke-linejoin="round"/><path d="M145 163 L155 181 M215 163 L205 181" stroke="#fff" stroke-width="5" stroke-linecap="round"/>`;
if(state.top==='underwear')shape=`<path d="M137 165 Q158 178 180 170 Q202 178 223 165 L231 211 Q207 227 180 210 Q153 227 129 211Z" fill="${c}" stroke="#fff" stroke-width="3"/><path d="M143 165 Q142 146 155 146 Q166 146 167 172 M194 172 Q196 146 209 146 Q222 147 218 165" fill="none" stroke="${c}" stroke-width="10" stroke-linecap="round"/><path d="M143 168 Q180 181 217 168" fill="none" stroke="#fff" stroke-width="2"/>`;
$('#topGarment').innerHTML=shape;}
function drawBottom(){const c=state.colors.bottoms;let shape='';if(state.bottom==='jeans')shape=`<path d="M137 314 Q180 323 224 314 L219 375 L219 439 L230 459 L212 470 L193 458 L189 374 L177 371 L172 456 L153 469 L132 459 L143 438 L141 374Z" fill="${c}" stroke="#fff" stroke-width="3" stroke-linejoin="round"/><path d="M143 337 Q180 345 218 337 M180 336v34 M148 351l18 3m45-3-18 3" fill="none" stroke="#fff" stroke-width="2" opacity=".8"/>`;
if(state.bottom==='shorts')shape=`<path d="M136 312 Q180 324 224 312 L220 372 Q204 381 180 371 Q156 382 140 372Z" fill="${c}" stroke="#fff" stroke-width="3"/><path d="M180 333v39 M144 340 Q180 350 217 340" fill="none" stroke="#fff" stroke-width="2"/>`;
if(state.bottom==='skirt')shape=`<path d="M138 314 Q180 324 222 314 L240 395 Q180 411 120 395Z" fill="${c}" stroke="#fff" stroke-width="3"/><path d="M131 345 Q180 357 229 345 M143 369q37 12 74 0" fill="none" stroke="#fff" stroke-width="3" opacity=".7"/>`;
if(state.bottom==='briefs')shape=`<path d="M137 310 Q180 322 224 310 L223 354 Q206 367 181 348 Q156 367 138 354Z" fill="${c}" stroke="#fff" stroke-width="3"/><path d="M140 316 Q180 328 221 316 M143 322 L151 352 M218 322 L210 352" fill="none" stroke="#fff" stroke-width="2"/>`;
if(state.bottom==='joggers')shape=`<path d="M137 312 Q180 322 224 312 L220 377 L224 449 Q208 457 190 450 L181 374 L174 374 L169 450 Q151 457 133 449 L142 377Z" fill="${c}" stroke="#fff" stroke-width="3"/><path d="M143 337 Q180 345 218 337 M180 341v30 M137 447q15 7 32 0m22 0q17 7 33 0" fill="none" stroke="#fff" stroke-width="3"/>`;
$('#bottomGarment').innerHTML=shape;}
function drawExtra(){let s='';const c=state.colors.extras;if(state.extra==='glasses')s=`<g fill="none" stroke="${c}" stroke-width="5"><rect x="143" y="82" width="27" height="20" rx="8"/><rect x="190" y="82" width="27" height="20" rx="8"/><path d="M170 89 Q180 84 190 89"/></g><path d="M148 87h16m33 0h15" stroke="#fff" stroke-width="2"/>`;
if(state.extra==='cap')s=`<path d="M128 66 Q131 29 177 27 Q220 28 231 67 L222 75 Q181 60 136 77Z" fill="${c}" stroke="#fff" stroke-width="3"/><path d="M129 67 Q164 59 207 72 Q224 77 236 84 Q205 93 178 78 Q151 72 129 76Z" fill="${c}" stroke="#fff" stroke-width="3"/><path d="M181 34v26" stroke="#fff" stroke-width="3"/>`;
if(state.extra==='bow')s=`<path d="M218 58 Q235 34 251 49 Q257 65 232 69 Q258 76 247 92 Q231 97 218 72 Q207 93 193 84 Q189 67 211 65 Q192 56 203 44 Q214 41 218 58Z" fill="${c}" stroke="#fff" stroke-width="3"/><circle cx="219" cy="68" r="7" fill="#ffcf5a"/>`;
if(state.extra==='scarf')s=`<path d="M154 141 Q180 153 207 141 L201 162 Q181 170 160 161Z" fill="${c}" stroke="#fff" stroke-width="2"/><path d="M197 158 L211 187 L199 193 L186 163Z" fill="${c}" stroke="#fff" stroke-width="2"/>`;
if(state.extra==='sneakers'){$('#shoes').innerHTML=`<path d="M132 458 Q143 466 177 457 L181 474 Q180 490 157 493 L119 491 Q113 483 123 475Z" fill="${c}"/><path d="M188 457 Q207 463 233 456 L243 475 Q247 489 226 493 L190 490 Q181 483 188 457Z" fill="${c}"/><path d="M121 484 Q144 489 176 482M191 482Q217 490 240 482" fill="none" stroke="#fff" stroke-width="4" stroke-linecap="round"/>`;}else{$('#shoes').innerHTML=`<path d="M132 458 Q143 466 177 457 L181 474 Q180 490 157 493 L119 491 Q113 483 123 475Z" fill="#ff704d"/><path d="M188 457 Q207 463 233 456 L243 475 Q247 489 226 493 L190 490 Q181 483 188 457Z" fill="#ff704d"/><path d="M121 484 Q144 489 176 482M191 482Q217 490 240 482" fill="none" stroke="#fff" stroke-width="4" stroke-linecap="round"/>`;}
$('#accessory').innerHTML=s;}
function render(){panel.innerHTML='';catalog[state.tab].forEach(item=>{const b=document.createElement('button');b.className='option'+(state[state.tab==='tops'?'top':state.tab==='bottoms'?'bottom':'extra']===item.id?' selected':'');b.setAttribute('aria-pressed',b.classList.contains('selected'));b.innerHTML=`<span class="option-icon">${item.icon}</span><span class="option-name">${item.name}</span>`;b.onclick=()=>{if(state.tab==='tops')state.top=item.id;else if(state.tab==='bottoms')state.bottom=item.id;else state.extra=item.id;render();};panel.appendChild(b);});document.querySelectorAll('.tab').forEach(t=>{const on=t.dataset.tab===state.tab;t.classList.toggle('active',on);t.setAttribute('aria-selected',on);});drawTop();drawBottom();drawExtra();drawSwatches();}
function drawSwatches(){const root=$('#swatches');root.innerHTML='';const color=state.colors[state.tab];palette.forEach(p=>{const b=document.createElement('button');b.className='swatch'+(color===p.hex?' active':'');b.style.background=p.hex;b.setAttribute('aria-label',p.name);b.setAttribute('aria-pressed',color===p.hex);b.onclick=()=>{state.colors[state.tab]=p.hex;$('#selectedColorName').textContent=p.name;render();};root.appendChild(b);});const current=palette.find(p=>p.hex===color);$('#selectedColorName').textContent=current?.name||'Custom';}
document.querySelectorAll('.tab').forEach(t=>t.addEventListener('click',()=>{state.tab=t.dataset.tab;render();}));
$('#nameInput').addEventListener('input',e=>{const n=e.target.value.trim().slice(0,12)||'Riley';$('#characterName').textContent=n;document.querySelector('.stage-caption').innerHTML=`<span class="caption-dot"></span> ${n} is a grown-up (25) & ready to play`;});
$('#pullRange').addEventListener('input',e=>$('#pullValue').textContent=e.target.value);
const lines=['Boing! Nailed the look!','Ha! That was a good one!','Fashion AND bounce!','Riley says: one more!','What a silly little hop!','Style points incoming!'];let toastTimer;
function message(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),1500);}
function chirp(){if(!state.sound)return;try{const ctx=new(window.AudioContext||window.webkitAudioContext)();[520,740,660].forEach((f,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=f;o.type='sine';g.gain.setValueAtTime(.055,ctx.currentTime+i*.09);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+i*.09+.12);o.start(ctx.currentTime+i*.09);o.stop(ctx.currentTime+i*.09+.13);});}catch{}}
$('#wedgieButton').addEventListener('click',()=>{if(state.busy)return;state.busy=true;const now=Date.now();state.combo=now-state.lastTug<4200?state.combo+1:1;state.lastTug=now;const strength=Number($('#pullRange').value),gain=strength*13+state.combo*5;state.score+=gain;$('#score').textContent=String(state.score).padStart(3,'0');$('#scoreBar').style.width=`${Math.min(100,state.score%500/5)}%`;$('#combo').textContent=state.combo>1?`×${state.combo} COMBO`:'NICE!';const wrap=$('#characterWrap');wrap.classList.remove('bounce');void wrap.offsetWidth;wrap.classList.add('bounce');const sp=$('#sparkles');sp.classList.remove('sparkle-on');void sp.getBoundingClientRect();sp.classList.add('sparkle-on');const pick=lines[Math.floor(Math.random()*lines.length)];$('#speech').textContent=pick;$('#stampText').textContent=state.score>=100?'BOING STAR':'STYLE ICON';chirp();message(`+${gain} style points! ${strength>=4?'Big bounce!':'Nice and goofy!'}`);setTimeout(()=>{state.busy=false;wrap.classList.remove('bounce');},880);});
$('#sound-toggle');$('.sound-toggle').addEventListener('click',e=>{state.sound=!state.sound;e.currentTarget.classList.toggle('active',state.sound);e.currentTarget.textContent=state.sound?'♫':'♪';e.currentTarget.setAttribute('aria-label',state.sound?'Turn sound off':'Turn sound on');message(state.sound?'Sound on!':'Sound off');});
$('#randomize').addEventListener('click',()=>{state.top=['tee','hoodie','tank','underwear'][Math.floor(Math.random()*4)];state.bottom=['jeans','shorts','skirt','briefs','joggers'][Math.floor(Math.random()*5)];state.extra=['glasses','cap','bow','scarf','sneakers','none'][Math.floor(Math.random()*6)];state.colors.tops=palette[Math.floor(Math.random()*palette.length)].hex;state.colors.bottoms=palette[Math.floor(Math.random()*palette.length)].hex;state.tab='tops';$('#speech').textContent='Surprise! A fresh new look!';render();message('A whole new look!');});
$('#resetButton').addEventListener('click',()=>{state.top='tee';state.bottom='jeans';state.extra='glasses';state.colors={tops:'#5a9ed6',bottoms:'#9871d5',extras:'#ff7f9f'};state.tab='tops';render();message('Back to the classic look!');});
render();

